	if joined(tokens) != prose {
		t.Errorf("coalescing changed the text: %q", joined(tokens))
	}

	for _, token := range Tokenize(KindMarkdown, sampleMarkdown) {
		if token.Text == "" {
			t.Error("an empty run survived coalescing")
		}
	}
}

